if (!defined('CLI_SCRIPT')) { define('CLI_SCRIPT', true); }
require('/www/moodle/config.php');
require_once($CFG->dirroot . '/course/lib.php');
require_once($CFG->dirroot . '/mod/questionnaire/lib.php');
try {
    global $DB, $USER, $CFG;
    $USER = get_admin();

    // Create the demo category and course from PHP so the setup is self-contained.
    $category = $DB->get_record('course_categories', ['name' => 'Demo Courses']);
    if (!$category) {
        $category = \core_course_category::create((object) ['name' => 'Demo Courses']);
    }
    $categoryid = is_object($category) ? $category->id : $category;

    $course = $DB->get_record('course', ['shortname' => 'questionnaire-demo']);
    if (!$course) {
        $course = create_course((object) [
            'fullname' => 'Questionnaire Demo',
            'shortname' => 'questionnaire-demo',
            'category' => $categoryid,
            'summary' => 'Demo course with a preconfigured Questionnaire activity, ready to preview at a glance.',
            'summaryformat' => FORMAT_HTML,
        ]);
    }

    // Enrol the admin as editing teacher (needed for the questionnaire preview and My courses).
    $manual = enrol_get_plugin('manual');
    $manualinstance = null;
    foreach (enrol_get_instances($course->id, false) as $inst) {
        if ($inst->enrol === 'manual') {
            $manualinstance = $inst;
            break;
        }
    }
    if (!$manualinstance && $manual) {
        $manualid = $manual->add_default_instance($course);
        $manualinstance = $manualid ? $DB->get_record('enrol', ['id' => $manualid]) : null;
    }
    $teacherrole = $DB->get_record('role', ['shortname' => 'editingteacher']);
    if ($manual && $manualinstance && $teacherrole) {
        $manual->enrol_user($manualinstance, $USER->id, $teacherrole->id);
    }

    // Create the questionnaire activity with three sample questions.
    if (!$DB->record_exists('questionnaire', ['course' => $course->id, 'name' => 'Course feedback survey'])) {
        $moduleid = $DB->get_field('modules', 'id', ['name' => 'questionnaire'], MUST_EXIST);

        // 1. Create the course module first (placeholder instance).
        $newcm = (object) [
            'course' => $course->id,
            'module' => $moduleid,
            'instance' => 0,
            'section' => 0,
            'added' => time(),
            'visible' => 1,
            'visibleoncoursepage' => 1,
            'visibleold' => 1,
            'groupmode' => 0,
            'groupingid' => 0,
        ];
        $cmid = add_course_module($newcm);

        // 2. Create the questionnaire instance. create='new-0' + empty sid makes
        //    questionnaire_add_instance() create the backing survey automatically.
        $qdata = (object) [
            'course' => $course->id,
            'coursemodule' => $cmid,
            'cmidnumber' => '',
            'name' => 'Course feedback survey',
            'intro' => '<p>A short sample survey. This preview shows all of its questions at a glance.</p>',
            'introformat' => FORMAT_HTML,
            'qtype' => 0,
            'respondenttype' => 'fullname',
            'resp_eligible' => 'all',
            'resp_view' => 0,
            'opendate' => 0,
            'closedate' => 0,
            'resume' => 0,
            'navigate' => 0,
            'grade' => 0,
            'sid' => 0,
            'completionsubmit' => 0,
            'autonum' => 3,
            'create' => 'new-0',
            'timemodified' => time(),
        ];
        $instanceid = questionnaire_add_instance($qdata);

        // 3. Link the course module to the new instance and place it in the section.
        $DB->set_field('course_modules', 'instance', $instanceid, ['id' => $cmid]);
        course_add_cm_to_section($course->id, $cmid, 0);

        // 4. Add sample questions into the survey (active questions have deleted = NULL).
        $survey = $DB->get_record('questionnaire', ['id' => $instanceid], '*', MUST_EXIST);
        $sid = $survey->sid;

        // Q1 - Yes/No (type_id 1).
        $DB->insert_record('questionnaire_question', (object) [
            'surveyid' => $sid, 'name' => 'Q1', 'type_id' => 1,
            'content' => 'Do you enjoy using Moodle?', 'position' => 1,
            'required' => 'y', 'length' => 0, 'precise' => 0,
        ]);

        // Q2 - Radio Buttons (type_id 4) with choices.
        $q2id = $DB->insert_record('questionnaire_question', (object) [
            'surveyid' => $sid, 'name' => 'Q2', 'type_id' => 4,
            'content' => 'Which is your favourite colour?', 'position' => 2,
            'required' => 'y', 'length' => 0, 'precise' => 0,
        ]);
        foreach (['Red', 'Green', 'Blue', 'Yellow'] as $choice) {
            $DB->insert_record('questionnaire_quest_choice', (object) [
                'question_id' => $q2id, 'content' => $choice, 'value' => null,
            ]);
        }

        // Q3 - Text Box (type_id 2).
        $DB->insert_record('questionnaire_question', (object) [
            'surveyid' => $sid, 'name' => 'Q3', 'type_id' => 2,
            'content' => 'Any comments or suggestions?', 'position' => 3,
            'required' => 'n', 'length' => 0, 'precise' => 0,
        ]);

        rebuild_course_cache($course->id, true);
    }

    if (!$DB->record_exists('questionnaire', ['course' => $course->id, 'name' => 'Course feedback survey'])) {
        throw new \RuntimeException('The Questionnaire activity is missing after provisioning.');
    }

    echo "Provisioned mod_questionnaire demo on course 'questionnaire-demo' with 3 sample questions.\n";
} catch (\Throwable $e) {
    fwrite(STDERR, 'mod_questionnaire demo provisioning failed: ' . $e->getMessage() . "\n");
}
